export const CHAIN_ID_TO_NAME: Record<number, string> = {
  1: "mainnet",
  42161: "arbitrum",
  8453: "base",
  80094: "berachain",
  10: "optimism",
  11155111: "sepolia",
  421614: "arbitrum-sepolia",
  84532: "base-sepolia",
  80084: "berachain-bartio",
  5: "goerli",
};

export const CHAIN_NAME_TO_ID: Record<string, number> = {
  mainnet: 1,
  arbitrum: 42161,
  base: 8453,
  berachain: 80094,
  optimism: 10,
  sepolia: 11155111,
  "arbitrum-sepolia": 421614,
  "base-sepolia": 84532,
  "berachain-bartio": 80084,
  goerli: 5,
};

/**
 * Get addresses for a specific chain by chain ID
 */
export function getAddressesForChain(chainId: number): ChainAddresses | undefined {
  const chainName = CHAIN_ID_TO_NAME[chainId];
  if (!chainName) return undefined;
  return EMERGENCY_ADDRESSES[chainName];
}
